  if hit && hit[1] && hit[1].include?(inst) && (mz - hit[0].z) > 400.mm
    anc = hit[0]
  end
  txt = entities.add_text("CHEMISTRY SHELF", anc, Geom::Vector3d.new(-200.mm, -850.mm, 700.mm))
  txt.layer = model.layers["Labels"] rescue nil
end
